/// SVG значка dropweb в круге: знак цветом [fg] на плашке [bg] (hex `#rrggbb`).
///
/// [uid] попадает в id маски; нужен, только если несколько SVG разбираются вместе.
String m3eAppIconSvg({
  required String fg,
  required String bg,
  String uid = 'ai',
}) =>
    kM3eAppIconTemplate
        .replaceAll('{{uid}}', uid)
        .replaceAll('{{bg}}', bg)
        .replaceAll('{{fg}}', fg);
